.wstactical__h2 em{color:#836d40}.wstactical__dva .wstactical__zak{border-left:3px solid #8b7444;padding-left:14px}
.wstactical__media,.wstactical__polna{box-shadow:0 14px 34px rgba(139,116,68,.22);border:1px solid rgba(139,116,68,.25)}
.wstactical__k{border:1px solid rgba(139,116,68,.35);border-radius:16px;box-shadow:0 6px 18px rgba(0,0,0,.05);transition:transform .2s,box-shadow .2s}.wstactical__k:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(139,116,68,.22)}
.wstactical__pog>div{border:1px solid rgba(139,116,68,.35);border-radius:16px;padding:28px 18px;transition:transform .2s,box-shadow .2s}.wstactical__pog>div:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(139,116,68,.22)}
span.wstactical__pi{opacity:1;width:58px;height:58px;border-radius:50%;background:#dcd5c7;border:1px solid #8b7444;color:#836d40;display:flex;align-items:center;justify-content:center;margin:0 auto 14px}.wstactical__pi svg{width:28px;height:28px}
.wstactical__red4:not(.wstactical__pog)>div{background:#fff;border:1px solid rgba(139,116,68,.35);border-radius:16px;padding:24px 16px;box-shadow:0 6px 18px rgba(0,0,0,.05)}.wstactical__red3 span.wstactical__pi{width:44px;height:44px;margin-bottom:8px}.wstactical__red3 .wstactical__pi svg{width:22px;height:22px}.wstactical__red3>div{border-color:rgba(139,116,68,.35)}
.wstactical__pog strong{color:#1c1c1c}.wstactical__st,.wstactical__kv li::before{background:#836d40}.wstactical__tab th{background:#836d40!important}
.wstactical__ti{background:linear-gradient(135deg,#836d40,#9e8d6a);box-shadow:0 6px 14px rgba(131,109,64,.30)}.wstactical__tk{border-color:rgba(139,116,68,.30)}
.wstactical__ime{display:flex;align-items:center;gap:10px}.wstactical__av{flex:0 0 34px;width:34px;height:34px;border-radius:50%;background:#dcd5c7;border:1px solid #8b7444;color:#836d40;font-style:normal;font-weight:800;font-size:14px;display:inline-flex;align-items:center;justify-content:center}
div.wstactical__pog{text-align:center;border:1px solid rgba(139,116,68,.35);border-radius:16px;transition:transform .2s,box-shadow .2s}div.wstactical__pog:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(139,116,68,.22)}div.wstactical__pog>strong,div.wstactical__pog>span:not(.wstactical__pi){display:block}
.wstactical__k--ik .wstactical__kt{text-align:center;padding:28px 20px}
.wstactical__pus{color:#836d40}.wstactical__plavo{background:#836d40;margin-top:-72px}.wstactical__k--temna{background:#836d40}
@media (max-width:860px){.wstactical__s{padding:46px 0}.wstactical__s.wstactical__traka{padding:30px 0}.wstactical__plavo{margin-top:-46px}.wstactical__pog>div{padding:22px 12px}}
@media (max-width:767px){.wstactical__v{padding:0 16px}}
/* /dizajn.py */
.wstactical__v>.wstactical__zak{text-align:center}
.wstactical__media--cela{background:#f4f4f4}
</style>
<script>
(function(){document.querySelectorAll('.wstactical__kar').forEach(function(k){
  var w=document.createElement('div');w.className='wstactical__karw';k.parentNode.insertBefore(w,k);w.appendChild(k);
  ['l','d'].forEach(function(s){var b=document.createElement('button');b.type='button';b.className='wstactical__pus wstactical__pus--'+s;b.setAttribute('aria-label',s==='l'?'Prethodno':'Sljedeće');b.innerHTML=s==='l'?'&#8249;':'&#8250;';
    b.addEventListener('click',function(){var x=k.firstElementChild;var d=x?x.getBoundingClientRect().width+22:300;k.scrollBy({left:s==='l'?-d:d,behavior:'smooth'});});w.appendChild(b);});
});})();
</script>
